 {id:'jss3-fac-04',prompt:'Factorize ax+ay.',options:['a(x+y)','a(xy)','x(a+y)','ay(a+x)'],correctAnswer:'a(x+y)',explanation:'a is common to both terms.',difficulty:1,skill:'nerdc-common-factor'},
 {id:'jss3-fac-05',prompt:'Factorize 12ab+18ac completely.',options:['6a(2b+3c)','3a(4b+6c)','6(2ab+3ac)','a(12b+18c)'],correctAnswer:'6a(2b+3c)',explanation:'6a is the highest common factor.',difficulty:2,skill:'common-factor'},
 {id:'jss3-fac-06',prompt:'Factorize 2x+2y+ax+ay by grouping.',options:['(2+a)(x+y)','(2+x)(a+y)','2a(x+y)','(x+a)(2+y)'],correctAnswer:'(2+a)(x+y)',explanation:'2(x+y)+a(x+y)=(2+a)(x+y).',difficulty:2,skill:'grouping'},
 {id:'jss3-fac-07',prompt:'Which expression is a difference of two squares?',options:['x²+25','x²−25','x²−10x+25','x²+10x+25'],correctAnswer:'x²−25',explanation:'It is x²−5².',difficulty:1,skill:'difference-squares-recognition'},
 {id:'jss3-fac-08',prompt:'Factorize x²−25.',options:['(x−5)(x+5)','(x−5)²','(x+5)²','(x−25)(x+1)'],correctAnswer:'(x−5)(x+5)',explanation:'a²−b²=(a−b)(a+b).',difficulty:1,skill:'difference-squares'},
 {id:'jss3-fac-09',prompt:'Factorize 9a²−16b².',options:['(3a−4b)(3a+4b)','(9a−16b)(a+b)','(3a−4b)²','(9a−4b)(a+4b)'],correctAnswer:'(3a−4b)(3a+4b)',explanation:'9a²=(3a)² and16b²=(4b)².',difficulty:2,skill:'difference-squares'},
 {id:'jss3-fac-10',prompt:'Factorize 12x²−48 completely.',options:['12(x²−4)','12(x−2)(x+2)','6(2x²−8)','4(3x²−12)'],correctAnswer:'12(x−2)(x+2)',explanation:'First take12, then x²−4 is a difference of squares.',difficulty:2,skill:'multi-stage'},
 {id:'jss3-fac-11',prompt:'Which identity is correct?',options:['a²−b²=(a−b)(a+b)','a²+b²=(a−b)(a+b)','a²−b²=(a−b)²','a²+b²=(a+b)²'],correctAnswer:'a²−b²=(a−b)(a+b)',explanation:'The middle terms cancel on expansion.',difficulty:1,skill:'identity'},
 {id:'jss3-fac-12',prompt:'Factorize x²+10x+25.',options:['(x+5)²','(x−5)²','(x+25)(x+1)','(x+10)(x+15)'],correctAnswer:'(x+5)²',explanation:'25=5² and10x=2×x×5.',difficulty:1,skill:'perfect-square'},
 {id:'jss3-fac-13',prompt:'Factorize x²−14x+49.',options:['(x−7)²','(x+7)²','(x−49)(x+1)','(x−14)(x+1)'],correctAnswer:'(x−7)²',explanation:'49=7² and−14x=−2×x×7.',difficulty:2,skill:'perfect-square'},
 {id:'jss3-fac-14',prompt:'Factorize 4a²−12ab+9b².',options:['(2a−3b)²','(2a+3b)²','(4a−9b)(a+b)','(2a−9b)(2a−b)'],correctAnswer:'(2a−3b)²',explanation:'It matches A²−2AB+B² with A=2a,B=3b.',difficulty:2,skill:'perfect-square'},
 {id:'jss3-fac-15',prompt:'Factorize x²+7x+12.',options:['(x+3)(x+4)','(x+2)(x+6)','(x−3)(x−4)','(x+1)(x+12)'],correctAnswer:'(x+3)(x+4)',explanation:'3×4=12 and3+4=7.',difficulty:1,skill:'quadratic'},
 {id:'jss3-fac-16',prompt:'Factorize x²−9x+20.',options:['(x−4)(x−5)','(x+4)(x+5)','(x−2)(x−10)','(x+4)(x−5)'],correctAnswer:'(x−4)(x−5)',explanation:'(−4)(−5)=20 and−4−5=−9.',difficulty:2,skill:'quadratic-signs'},
 {id:'jss3-fac-17',prompt:'Factorize x²+x−12.',options:['(x+4)(x−3)','(x−4)(x+3)','(x+6)(x−2)','(x−6)(x+2)'],correctAnswer:'(x+4)(x−3)',explanation:'4×−3=−12 and4−3=1.',difficulty:2,skill:'quadratic-signs'},
 {id:'jss3-fac-18',prompt:'For 2x²+7x+3, which pair splits the middle term using the ac method?',options:['6 and1','3 and2','−6 and−1','7 and1'],correctAnswer:'6 and1',explanation:'a×c=2×3=6 and6+1=7.',difficulty:2,skill:'quadratic-box'},
 {id:'jss3-fac-19',prompt:'Factorize 2x²+7x+3.',options:['(2x+1)(x+3)','(2x+3)(x+1)','(x+1)(x+3)','(2x−1)(x−3)'],correctAnswer:'(2x+1)(x+3)',explanation:'Split7x as6x+x and group.',difficulty:2,skill:'quadratic-box'},
 {id:'jss3-fac-20',prompt:'Factorize 3x²+15x+18 completely.',options:['3(x+2)(x+3)','3(x²+5x+6)','(3x+6)(x+3)','3x(x+5)+18'],correctAnswer:'3(x+2)(x+3)',explanation:'Take HCF3, then factor x²+5x+6.',difficulty:2,skill:'multi-stage'},
 {id:'jss3-fac-21',prompt:'What is the best first check before factorizing any polynomial at this level?',options:['Look for a common factor','Always use difference of squares','Always draw a quadratic box','Divide by x'],correctAnswer:'Look for a common factor',explanation:'Removing an HCF first simplifies the remaining structure.',difficulty:1,skill:'method-selection'},
 {id:'jss3-fac-22',prompt:'Which cannot be factorized by the difference-of-two-squares identity?',options:['x²−16','9a²−25','4m²−n²','x²+16'],correctAnswer:'x²+16',explanation:'The identity requires a difference, not a sum.',difficulty:2,skill:'method-selection'},
 {id:'jss3-fac-23',prompt:'A rectangle has area x²+7x+12. Which pair can represent its algebraic dimensions?',options:['x+3 and x+4','x+2 and x+6','x−3 and x−4','x+1 and x+12'],correctAnswer:'x+3 and x+4',explanation:'x²+7x+12=(x+3)(x+4).',difficulty:2,skill:'word-problem'},
 {id:'jss3-fac-24',prompt:'A rectangle has area 2x²+7x+3. Which dimensions reproduce the area?',options:['2x+1 and x+3','2x+3 and x+1','x+1 and x+3','2x−1 and x−3'],correctAnswer:'2x+1 and x+3',explanation:'(2x+1)(x+3)=2x²+7x+3.',difficulty:3,skill:'word-problem'},
 {id:'jss3-fac-25',prompt:'Why is expansion useful after factorisation?',options:['It verifies that the factors reproduce the original expression','It always makes the expression shorter','It changes a quadratic to a linear expression','It removes variables'],correctAnswer:'It verifies that the factors reproduce the original expression',explanation:'Factorisation and expansion are inverse processes.',difficulty:1,skill:'verification'},
 {id:'jss3-fac-26',prompt:'A student writes x²−16=(x−4)². What is wrong?',options:['(x−4)² expands to x²−8x+16, not x²−16','16 is not a square','x² cannot be factorized','The answer should contain no brackets'],correctAnswer:'(x−4)² expands to x²−8x+16, not x²−16',explanation:'The correct difference-of-squares factorisation is(x−4)(x+4).',difficulty:2,skill:'error-analysis'},
 {id:'jss3-fac-27',prompt:'Factorize 18a²−50 completely.',options:['2(3a−5)(3a+5)','2(9a²−25)','(18a−50)(a+1)','6(3a²−25)'],correctAnswer:'2(3a−5)(3a+5)',explanation:'18a²−50=2(9a²−25)=2(3a−5)(3a+5).',difficulty:3,skill:'multi-stage'},
 {id:'jss3-fac-28',prompt:'Factorize 9x²−24xy+16y².',options:['(3x−4y)²','(3x+4y)²','(9x−16y)(x+y)','(3x−8y)(3x−2y)'],correctAnswer:'(3x−4y)²',explanation:'It is A²−2AB+B² with A=3x,B=4y.',difficulty:3,skill:'perfect-square'},
 {id:'jss3-fac-29',prompt:'Factorize 2x²−10x+12 completely.',options:['2(x−2)(x−3)','2(x+2)(x+3)','(2x−2)(x−6)','2(x²−5x+6)'],correctAnswer:'2(x−2)(x−3)',explanation:'Take2, then x²−5x+6=(x−2)(x−3).',difficulty:3,skill:'multi-stage'},
 {id:'jss3-fac-30',prompt:'Which pair has product −15 and sum −2?',options:['3 and−5','−3 and5','1 and−15','−1 and15'],correctAnswer:'3 and−5',explanation:'3×−5=−15 and3+(−5)=−2.',difficulty:2,skill:'product-sum'},
 {id:'jss3-fac-31',prompt:'Factorize x²−2x−15.',options:['(x+3)(x−5)','(x−3)(x+5)','(x−1)(x+15)','(x+1)(x−15)'],correctAnswer:'(x+3)(x−5)',explanation:'3×−5=−15 and3−5=−2.',difficulty:2,skill:'quadratic'},
 {id:'jss3-fac-32',prompt:'Factorize 5x²+25x+30 completely.',options:['5(x+2)(x+3)','5(x+5)(x+6)','5x(x+5)+30','(5x+2)(x+15)'],correctAnswer:'5(x+2)(x+3)',explanation:'Take5:5(x²+5x+6)=5(x+2)(x+3).',difficulty:3,skill:'bece-mixed'},
 {id:'jss3-fac-33',prompt:'Which is a correct factorisation of −8a²−12a?',options:['−4a(2a+3)','−4a(2a−3)','4a(−2a+3)','−2a(4a−6)'],correctAnswer:'−4a(2a+3)',explanation:'Expanding gives−8a²−12a.',difficulty:2,skill:'negative-common-factor'},
 {id:'jss3-fac-34',prompt:'If a four-term expression is factorized by grouping, what must normally appear after factoring each pair?',options:['The same bracket factor','The same numerical coefficient only','No variables','A square root'],correctAnswer:'The same bracket factor',explanation:'That common binomial can then be factored out.',difficulty:2,skill:'grouping'},
 {id:'jss3-fac-35',prompt:'The printed NERDC example 3m+pq+3p+mp does not produce matching brackets under ordinary grouping. What should a careful learner do?',options:['Change a term silently','Force two unlike brackets to be equal','Preserve the expression and verify whether a proposed factorisation expands back correctly','Assume the answer is(m+p)(3+q) without checking'],correctAnswer:'Preserve the expression and verify whether a proposed factorisation expands back correctly',explanation:'A factorisation must reproduce the exact original expression; terms must never be silently altered.',difficulty:3,skill:'source-critical-reasoning'},
 {id:'jss3-fac-36',prompt:'Factorize 4x²−4x−24 completely.',options:['4(x−3)(x+2)','4(x+3)(x−2)','2(2x−3)(x+4)','4(x²−x−6)'],correctAnswer:'4(x−3)(x+2)',explanation:'Take4, then x²−x−6 uses−3 and2.',difficulty:3,skill:'final-mastery'}
