export const jss3FractionEquationsTopic='Simple Equations Involving Fractions (LCM method, exam-style word problems)';

export const jss3FractionEquationsPlan:TutorPlan={
 goal:'Solve JSS3 simple equations involving fractions accurately by the LCM method, explain every transformation, verify solutions by substitution, and model NERDC/BECE word problems with fractional relationships.',
 why:'NERDC requires learners to solve simple equations involving fractions and solve word problems leading to such equations. Reliable mastery depends on denominator/LCM fluency, equality principles and correct translation—not shortcuts.',
 outcomes:[
  'Identify denominators and find the LCM needed to clear fractions.',
  'Explain why multiplying every term on both sides by the same non-zero LCM preserves equality.',
  'Solve equations with one or several fractional terms.',
  'Solve equations containing fractional expressions in brackets or numerators.',
  'Solve equations with fractions on both sides.',
  'Handle negative signs and subtraction of fractional expressions correctly.',
  'Check solutions by substitution into the original fractional equation.',
  'Translate age, number, sharing and quantity word problems into fractional equations.',
  'Solve mixed BECE-style fractional-equation problems and diagnose common errors.'
 ],
 examFocus:[
  'Find the LCM of all denominators in the entire equation before clearing fractions.',
  'Multiply EVERY term on BOTH sides by the LCM.',
  'Cancel the LCM with each denominator before multiplying what remains.',
  'If a numerator contains more than one term, preserve it as a grouped expression.',
  'After fractions are cleared, simplify brackets and collect variable terms carefully.',
  'Do not cross-multiply blindly when an equation contains sums or more than one fraction.',
  'Check the final value in the original equation, not only the cleared equation.',
  'In word problems, define the unknown before forming the equation.'
 ],
 units:[
  {title:'Foundation: what an equation means',terms:[['equation','statement that two expressions are equal'],['left-hand side','expression to the left of ='],['right-hand side','expression to the right of ='],['solution','value that makes the equation true']],explain:'An equation is a balance. Whatever valid operation is applied to the whole left side must also be applied to the whole right side. This balance principle is the reason the LCM method works: multiplying both sides by the same non-zero number produces an equivalent equation.',example:'x+3=8. Subtract3 from both sides: x=5. Check:5+3=8.',check:'Explain why multiplying both sides of x/3=4 by3 does not change the solution.',commonMistakes:['treating = as a command to calculate rather than a balance','changing only one side','calling any rearranged expression the solution before isolating the variable']},
  {title:'Fraction foundation: numerator, denominator and equivalent fractions',terms:[['numerator','top part of a fraction'],['denominator','bottom part of a fraction'],['equivalent fractions','fractions with the same value']],explain:'In a/b, a is the numerator and b is the denominator, with b≠0. Equation work often changes the appearance of fractions without changing their values. Understanding equivalent fractions and cancellation prevents mechanical LCM mistakes.',example:'2/3=4/6 because numerator and denominator were both multiplied by2.',check:'Write two fractions equivalent to3/5.',commonMistakes:['cancelling across addition','allowing denominator zero','multiplying only a numerator when forming an equivalent fraction']},
  {title:'Finding LCM of denominators',terms:[['multiple','product of a number and an integer'],['LCM','least positive common multiple']],explain:'The LCM is the smallest number divisible by every denominator. It is ideal for clearing fractions because each denominator divides it exactly. Use known multiples or prime factors. For 4 and6, multiples first meet at12; for3,4,6 the LCM is12.',example:'Denominators6,8,12:6=2×3;8=2³;12=2²×3. Take highest powers2³×3=24.',check:'Find the LCM of4,6 and10.',commonMistakes:['using the HCF instead of LCM','multiplying all denominators even when a smaller LCM exists','forgetting one denominator']},
  {title:'Why the LCM clears fractions',terms:[['clear fractions','multiply through so fractional denominators cancel'],['equivalent equation','equation with exactly the same solution set']],explain:'Suppose x/3+1/2=5. Denominators are3 and2, LCM6. Multiply the entire equation by6:6(x/3)+6(1/2)=6(5). Cancel:2x+3=30. The fractions disappear because6÷3=2 and6÷2=3. Every term must be multiplied.',example:'For x/4+2=5, multiply every term by4: x+8=20, so x=12.',check:'Clear the fractions in x/5+1/2=3 without solving further.',commonMistakes:['multiplying only fractional terms','multiplying only one side','multiplying numerators and denominators by the LCM instead of cancelling correctly']},
  {title:'One fractional variable term',terms:[['inverse operation','operation used to undo another operation']],explain:'If the variable is divided by a number, multiplying both sides by that denominator isolates it when no other term interferes.',example:'x/7=5 → multiply both sides by7 → x=35. Check:35/7=5.',check:'Solve x/9=4 and verify.',commonMistakes:['dividing by the denominator again','multiplying only the left side','forgetting to substitute back']},
  {title:'Fractional variable plus a whole-number term',terms:[['isolate','leave the variable alone on one side']],explain:'You may first remove the whole-number term or clear fractions first. The LCM method is consistent and especially useful when questions become harder. For x/3+4=9, multiply by3: x+12=27; x=15.',example:'x/5−2=4 → multiply by5: x−10=20 → x=30.',check:'Solve x/4+3=8.',commonMistakes:['multiplying x but not the whole-number term','losing a subtraction sign','stopping after clearing the fraction']},
  {title:'Two fractional terms with different denominators',terms:[['common denominator','shared denominator used to combine fractions']],explain:'Find one LCM for all denominators. For x/3+x/4=7, LCM12. Multiply through:4x+3x=84;7x=84;x=12. Check in original:12/3+12/4=4+3=7.',example:'x/2+x/5=14 → LCM10 →5x+2x=140 →7x=140 →x=20.',check:'Solve x/3+x/6=9.',commonMistakes:['adding denominators','using different multipliers without preserving equality','forgetting to combine like x terms']},
  {title:'Variable and constant fractions together',terms:[['constant','term without the variable']],explain:'Treat every denominator equally when finding the LCM. After clearing fractions, the equation becomes an ordinary linear equation.',example:'x/4+1/3=7/6. LCM12:3x+4=14;3x=10;x=10/3. A fractional solution is perfectly valid.',check:'Solve x/5+1/2=9/10.',commonMistakes:['assuming x must be an integer','ignoring the denominator of the right side','rounding an exact fractional solution']},
  {title:'Fraction on each side',terms:[['variable terms','terms containing the unknown']],explain:'Clear all denominators first, then collect variable terms on one side and constants on the other. Keep the equality balanced.',example:'x/3+2=x/6+5. LCM6:2x+12=x+30; subtract x: x+12=30;x=18. Check:6+2=3+5=8.',check:'Solve x/4+3=x/2−1.',commonMistakes:['cross-multiplying across a sum','moving a term without changing its sign through a valid inverse operation','forgetting one denominator']},
  {title:'A whole expression in the numerator',terms:[['fractional expression','fraction whose numerator or denominator contains an algebraic expression'],['grouping','treating several numerator terms as one quantity']],explain:'In (x+3)/4=5, the numerator x+3 is one grouped quantity. Multiply by4: x+3=20; x=17. Do not cancel4 with only x or only3.',example:'(2x−1)/5=3 →2x−1=15 →2x=16 →x=8.',check:'Solve (x−5)/3=7.',commonMistakes:['distributing the denominator incorrectly','cancelling part of a sum','forgetting the sign inside the numerator']},
  {title:'Fractional expressions plus other terms',terms:[['distribution','multiplying a factor by every term inside brackets']],explain:'When the LCM cancels a denominator, preserve the numerator bracket until it is safe to expand. Example:(x+2)/3+1/2=4. LCM6 gives2(x+2)+3=24; then2x+4+3=24;2x=17;x=17/2.',example:'(2x−3)/4+1=5 → multiply4:2x−3+4=20 →2x+1=20 →x=19/2.',check:'Solve (x+1)/2+3/4=11/4.',commonMistakes:['writing2(x+2) as2x+2','dropping brackets too early','rejecting a fractional answer']},
  {title:'Brackets outside fractional terms',terms:[['distributive law','a(b+c)=ab+ac']],explain:'Some equations combine ordinary brackets and fractions. Clear fractions, then expand brackets systematically. Alternatively expand first if it simplifies the structure; both routes must preserve equality.',example:'2(x/3+1)=6. Divide by2 first: x/3+1=3; x/3=2;x=6. Or clear denominator after expansion. Choose the cleanest valid path.',check:'Solve3(x/4−1)=6.',commonMistakes:['multiplying only the first bracket term','confusing an outside multiplier with a denominator','performing several mental steps without showing sign changes']},
  {title:'Negative fractional terms',terms:[['negative fraction','fraction whose overall value is negative']],explain:'A minus sign before a fraction applies to the entire fraction. When multiplying by the LCM, preserve that sign. For x/2−(x+1)/3=4, LCM6 gives3x−2(x+1)=24.',example:'3x−2x−2=24 →x−2=24 →x=26. Check:13−27/3=13−9=4.',check:'Solve x/3−(x−2)/2=1.',commonMistakes:['changing −2(x+1) to−2x+2','losing the negative sign during cancellation','subtracting denominators']},
  {title:'Equations where the variable has a coefficient in a fraction',terms:[['coefficient','number multiplying the variable']],explain:'Treat 3x/4 as one term. Clearing denominator4 gives3x. Continue with ordinary inverse operations.',example:'3x/4=9 →3x=36 →x=12. For 2x/3+5=11: multiply3 →2x+15=33 →2x=18 →x=9.',check:'Solve5x/6−2=8.',commonMistakes:['turning3x/4 into3+x/4','dividing by coefficient before handling the equation consistently','forgetting whole-number terms when multiplying through']},
  {title:'Several denominators on both sides',terms:[['global LCM','LCM taken from every denominator appearing anywhere in the equation']],explain:'Scan the whole equation before starting. Example x/2+1/3=x/4+5/6 has denominators2,3,4,6; LCM12. Multiply every term by12:6x+4=3x+10;3x=6;x=2.',example:'Check x=2:1+1/3=1/2+5/6=4/3.',check:'Solve x/3+1/4=x/6+3/4.',commonMistakes:['finding separate LCMs for each side and applying them inconsistently','missing a denominator','not simplifying after fractions clear']},
  {title:'When cross-multiplication is valid—and when it is not',terms:[['proportion','equality of two single ratios'],['cross multiplication','for a/b=c/d, forming ad=bc when denominators are non-zero']],explain:'Cross multiplication is valid when each side is a single fraction/ratio, such as (x+1)/3=5/2. It is not a magic rule across sums such as x/3+1/2=4. In multi-term equations use the LCM method.',example:'(x+1)/3=5/2 →2(x+1)=15 →2x=13 →x=13/2. But x/3+1/2=4 requires LCM6.',check:'State whether cross multiplication is appropriate for x/5=7/3 and for x/5+1/2=7/3.',commonMistakes:['cross-multiplying through plus signs','forgetting brackets around a multi-term numerator','using cross multiplication where the LCM method is clearer']},
  {title:'Checking a solution by substitution',terms:[['substitution','replacing the variable by the proposed value']],explain:'Put the answer into the ORIGINAL equation. Evaluate left and right sides independently. They must be equal. This catches LCM, sign and arithmetic mistakes.',example:'For x/3+x/4=7, x=12 gives4+3=7, so the solution is correct.',check:'Verify x=18 in x/3+2=x/6+5.',commonMistakes:['checking only the cleared equation','changing the original while substituting','accepting approximately equal sides for an exact equation']},
  {title:'Diagnosing an LCM-method error',terms:[['error diagnosis','identifying the first invalid transformation']],explain:'Suppose x/3+2=5 is multiplied by3 and a student writes x+2=15. The error is that3×2=6, not2. Correct equation is x+6=15, so x=9. Locate the first wrong line rather than only replacing the final answer.',example:'For x/4+1/2=3, LCM4 gives x+2=12, not x+1/2=12.',check:'A student changes x/5+3=7 to x+3=35. Identify and correct the error.',commonMistakes:['criticising only the final value','forgetting that every term is multiplied','redoing the problem without explaining the error']},
  {title:'Word-problem foundation: define, translate, solve, check',terms:[['unknown','quantity represented by a variable'],['model','equation representing the relationships in a problem']],explain:'Use four stages: define x; translate each phrase; form one equation; solve and interpret the answer in context. A mathematically correct equation can still answer the wrong quantity if x was not defined clearly.',example:'“One-third of a number plus5 is11.” Let x=number. x/3+5=11. Multiply3:x+15=33;x=18. Check:6+5=11.',check:'Translate “one-quarter of a number decreased by2 is7” into an equation.',commonMistakes:['using x without defining it','turning “of” into addition','giving x without units/context where units are relevant']},
  {title:'Number problems involving fractions',terms:[['fraction of a number','multiplication of the number by a fraction']],explain:'Phrases such as half of a number, two-thirds of a number and three-quarters of a number translate to x/2,2x/3 and3x/4. Combine them according to the sentence before solving.',example:'Two-thirds of a number plus4 is18:2x/3+4=18. Multiply3:2x+12=54;2x=42;x=21.',check:'Three-quarters of a number minus5 is16. Find the number.',commonMistakes:['writing2/(3x) instead of2x/3','multiplying the constant by the fraction without reason','solving before translating the complete statement']},
  {title:'Age problems with fractional relationships',terms:[['present age','current age represented by the variable'],['age relation','equation connecting ages']],explain:'Define one age and express the other from the relationship. Fractions often describe one person’s age as a fraction of another. Keep ages positive and check whether the result makes sense.',example:'A father is x years old. His son is one-third of his age. If their ages total48: x+x/3=48. LCM3:3x+x=144;4x=144;x=36, son=12.',check:'A mother’s age is x and her daughter is half her age. Their total age is54. Find both ages.',commonMistakes:['using the same variable for two ages without a relationship','forgetting the total includes both people','reporting only x when the question asks both ages']},
  {title:'Sharing and quantity problems',terms:[['remaining quantity','amount left after a stated fraction or amount is used']],explain:'Translate what is taken, used or shared and what remains. If a fraction of a total is used, subtract that fraction from the total or form the stated equation directly.',example:'One-quarter of a quantity plus12 equals27. Let total=x: x/4+12=27 →x+48=108 →x=60.',check:'One-fifth of a number added to the number gives72. Find the number.',commonMistakes:['confusing one-fifth of x with x−5','forgetting that “added to the number” includes x itself','ignoring context when checking']},
  {title:'Equations from perimeter/measurement contexts',terms:[['perimeter','total distance around a shape']],explain:'Measurement word problems can produce fractional equations when a side is a fraction of another quantity. Define the unknown length, express all sides, then use the perimeter relationship.',example:'A rectangle has length x cm and width x/2 cm. Perimeter is36:2(x+x/2)=36. Divide2:x+x/2=18. Multiply2:2x+x=36;3x=36;x=12, width6.',check:'A rectangle has length x and width x/3; perimeter32. Find both dimensions.',commonMistakes:['using area formula for a perimeter question','forgetting both pairs of sides','losing units']},
  {title:'Fractional equations producing fractional answers',terms:[['exact fraction','fraction retained without decimal approximation']],explain:'An answer need not be a whole number. Unless the context requires a whole count, an exact fraction can be correct. Keep exact fractions when possible rather than rounding.',example:'x/4+1/3=7/6 gives3x+4=14, so x=10/3. Substitution confirms it exactly.',check:'Solve x/2+1/3=5/6 and leave the answer exact.',commonMistakes:['rounding unnecessarily','assuming a fraction means the solution is wrong','converting to a recurring decimal and losing exactness']},
  {title:'Equations with brackets after clearing denominators',terms:[['collect like terms','combine terms with the same variable part']],explain:'LCM multiplication may create brackets. Expand them correctly, then collect like terms. Example (x+1)/2−(x−2)/3=4. LCM6:3(x+1)−2(x−2)=24;3x+3−2x+4=24;x+7=24;x=17.',example:'Check x=17:18/2−15/3=9−5=4.',check:'Solve (x+2)/3−(x−1)/4=2.',commonMistakes:['forgetting the minus changes every term in the second bracket','combining unlike terms','removing brackets before applying their multipliers']},
  {title:'Variable terms that cancel',terms:[['identity/no-solution test','examining what remains when variable terms disappear']],explain:'Occasionally clearing fractions and simplifying removes x. If both sides reduce to the same true statement, every allowed x satisfies the equation; if they reduce to a false statement, there is no solution. This is an extension useful for error awareness, though standard NERDC simple-equation items normally have one solution.',example:'x/2+1=x/2+1 simplifies to1=1: an identity. x/2+1=x/2+3 simplifies to1=3: no solution.',check:'Classify x/3+2=x/3+2 and x/4+1=x/4−2.',commonMistakes:['writing x=0 whenever x cancels','continuing to divide by a zero coefficient','confusing an identity with one numerical solution']},
  {title:'BECE-style multi-step equation',terms:[['multi-step equation','equation requiring several valid transformations']],explain:'Harder questions combine denominators, brackets and variable terms on both sides. Work one justified line at a time. Avoid doing too many mental transformations at once.',example:'(2x−1)/3+1/2=(x+5)/6. LCM6:2(2x−1)+3=x+5 →4x−2+3=x+5 →4x+1=x+5 →3x=4 →x=4/3. Substitute to check.',check:'Solve (x+3)/4+(x−1)/2=5.',commonMistakes:['using the wrong global LCM','distributing multipliers incorrectly','moving several terms and losing signs']},
  {title:'BECE-style reverse construction',terms:[['reverse problem','using a stated solution/relationship to infer an unknown quantity']],explain:'Some exam reasoning asks for a missing constant rather than x. Treat that constant as the unknown and substitute the known solution first.',example:'If x=6 satisfies x/3+k/2=5, then2+k/2=5 →k/2=3 →k=6.',check:'If x=8 satisfies x/4+k/3=5, find k.',commonMistakes:['solving for x even though x is already known','not substituting before clearing fractions','forgetting the new unknown may also be fractional']},
  {title:'Final exam routine for fractional equations',terms:[['solution discipline','consistent sequence reducing avoidable exam errors']],explain:'Use: (1) define unknown if contextual; (2) copy equation accurately; (3) list denominators; (4) find LCM; (5) multiply every term on both sides; (6) cancel denominators; (7) expand brackets; (8) collect variable and constant terms; (9) solve; (10) substitute into the original equation; (11) answer the actual question with units/context.',example:'For x/3+x/4=7: denominators3,4→LCM12→4x+3x=84→7x=84→x=12→check4+3=7.',check:'State why step10 must use the original equation.',commonMistakes:['skipping the denominator scan','checking a copied/altered equation instead of the original','giving a context-free value when the question asks for an age or length']
  }
 ]
};

