export const jss3SimultaneousLinearTopic='Simultaneous Linear Equations (tables, graphs, elimination, substitution, real-life problems)';

export const jss3SimultaneousLinearPlan:TutorPlan={
 goal:'Solve and interpret simultaneous linear equations in two variables using tables/graphs, elimination and substitution, and apply the methods to JSS3/BECE real-life problems.',
 why:'NERDC explicitly requires tables of values, graphical solutions, elimination, substitution, and real-life applications of both algebraic methods. Learners must understand that the solution is the ordered pair satisfying both equations at the same time.',
 outcomes:[
  'Explain a linear equation in two variables and the meaning of a simultaneous solution.',
  'Compile accurate tables of values for linear functions.',
  'Choose a useful scale, plot ordered pairs and draw straight-line graphs accurately.',
  'Read the intersection of two graphs as the simultaneous solution.',
  'Solve simultaneous equations by elimination when coefficients match or require multipliers.',
  'Choose whether to add or subtract equations during elimination and justify the choice.',
  'Solve simultaneous equations by substitution by making one variable the subject.',
  'Check an ordered-pair solution in both original equations.',
  'Translate number, cost, age and quantity situations into two simultaneous equations.',
  'Choose an efficient method and solve BECE-style mixed problems.'
 ],
 examFocus:[
  'A simultaneous solution must satisfy BOTH original equations.',
  'For a graph, make one variable the subject when useful, calculate enough points, label axes and scale, plot accurately, and read the intersection as (x,y).',
  'Graphical answers can be approximate because of drawing/reading accuracy; algebraic methods can give exact values.',
  'In elimination, equal coefficients with opposite signs are added; equal coefficients with the same sign are subtracted.',
  'If coefficients are unequal, multiply one or both complete equations by suitable numbers before eliminating.',
  'In substitution, isolate a convenient variable first; substitute the entire expression using brackets where necessary.',
  'Never multiply only one term of an equation when preparing coefficients.',
  'After finding one variable, substitute back to find the other.',
  'Verify the final ordered pair in both original equations.',
  'For word problems, define both unknowns and form two independent equations before solving.'
 ],
 units:[
  {title:'Foundation: linear equations in two variables',terms:[['linear equation','equation in which variables have power1 and its graph is a straight line'],['variable','unknown represented by a letter'],['ordered pair','pair (x,y) whose order matters']],explain:'An equation such as x+y=5 contains two variables. It does not usually have just one solution: (0,5),(1,4),(2,3) and many other pairs satisfy it. Each solution pair is a point on one straight line.',example:'For x+y=5, when x=2, y=3. Check:2+3=5.',check:'Give three ordered pairs satisfying x+y=6.',commonMistakes:['expecting one x value from one equation with two unknowns','reversing (x,y)','using a pair without checking it']},
  {title:'What simultaneous means',terms:[['simultaneous equations','two or more equations considered together'],['common solution','values satisfying every equation at the same time']],explain:'For two linear equations in x and y, we seek one ordered pair that makes both true. A pair satisfying only one equation is not a simultaneous solution.',example:'x+y=7 and x−y=1. (4,3) works because4+3=7 and4−3=1.',check:'Does (3,2) solve both x+y=5 and2x+y=8?',commonMistakes:['checking only the first equation','reporting x without y','treating the two equations as unrelated']},
  {title:'Why two lines reveal the solution',terms:[['intersection','point where two graphs meet'],['coordinate','number locating a point along an axis']],explain:'Each equation produces a straight line containing all its solution pairs. A point on both lines satisfies both equations. Therefore the intersection coordinate is the graphical simultaneous solution.',example:'If lines meet at (2,3), then x=2,y=3 must satisfy both equations represented by those lines.',check:'What does an intersection at (−1,4) mean algebraically?',commonMistakes:['reading only one coordinate','using an axis intercept instead of the intersection','assuming any point near both lines is exact']},
  {title:'Making y the subject for a table',terms:[['subject','variable isolated on one side'],['table of values','organized x-values and corresponding y-values']],explain:'A graph table is easiest when y is isolated. From2x+y=6, subtract2x: y=6−2x. Choose convenient x values and calculate y for each one.',example:'For y=6−2x: x=0→y=6; x=1→4; x=2→2; x=3→0.',check:'Make y the subject of x+2y=6.',commonMistakes:['moving a term without changing its sign correctly','dividing only one term when isolating y','changing the original equation']},
  {title:'Compiling a complete table of values',terms:[['corresponding value','y-value produced by a chosen x-value']],explain:'Choose enough x-values to draw the line confidently—normally at least three in a learning exercise. Substitute each x carefully and record its matching y. Negative x-values are allowed.',example:'For y=x+1 and x=−2,−1,0,1,2, the y-values are−1,0,1,2,3.',check:'Compile values for y=2x−1 at x=−1,0,1,2.',commonMistakes:['calculating all y-values mentally without checking','putting y-values under the wrong x-values','treating −2²-type sign issues carelessly in later topics']},
  {title:'Checking a table before graphing',terms:[['substitution check','putting a table pair back into the original equation']],explain:'One wrong table value can bend or misplace a line. Check at least one or two pairs in the original equation. For a linear function, correctly plotted points should lie on one straight line.',example:'For2x+y=6, pair(1,4) checks because2(1)+4=6.',check:'Is (2,1) a correct table point for y=2x−3?',commonMistakes:['graphing an unchecked table','altering the equation during the check','assuming a straight ruler line can repair a wrong point']},
  {title:'Graph axes, scale and plotting discipline',terms:[['x-axis','horizontal axis'],['y-axis','vertical axis'],['scale','value represented by each equal interval']],explain:'Draw perpendicular axes, label x and y, mark a uniform scale and plot (x,y) by moving horizontally to x then vertically to y. Choose a scale that includes all needed points and uses the graph space well.',example:'To plot (−2,3), move2 units left from origin then3 units up.',check:'Describe how to plot (3,−2).',commonMistakes:['changing scale midway','swapping axes','failing to label scale or axes']},
  {title:'Drawing the straight lines',terms:[['best straight line','single straight line passing through the accurately plotted collinear points']],explain:'After plotting at least two correct points, use a ruler to draw the line. More points help detect table/plotting mistakes. Extend the lines enough to show their intersection.',example:'Points(0,4),(1,3),(2,2) for y=4−x lie on one straight line.',check:'Why is a third table point useful even though two points determine a line?',commonMistakes:['joining points with separate zig-zag segments','freehand drawing','stopping the line before the intersection region']},
  {title:'Graphical solution step by step',terms:[['graphical solution','solution obtained from the intersection of plotted equation lines']],explain:'For x+y=5 and x−y=1, rewrite as y=5−x and y=x−1. Build tables, plot both on the same axes, draw straight lines, locate their intersection, then read x and y. The lines meet at(3,2).',example:'Check algebraically:3+2=5 and3−2=1.',check:'What five main stages are needed from equations to graphical answer?',commonMistakes:['using separate axes for the two equations','reading the wrong crossing','not writing the answer as an ordered pair']},
  {title:'Graphical accuracy and approximate answers',terms:[['approximation','value close to the exact value'],['reading error','small discrepancy caused by scale/line thickness/plotting']],explain:'A graph may give x≈2.5 rather than an exact fraction because of scale and drawing. That does not make the method invalid. Use a sensible scale, sharp pencil and ruler. If an exact algebraic answer is known, the graph should be reasonably close.',example:'If exact x=7/3≈2.33, a well-drawn graph may be read near2.3.',check:'Why might two careful students obtain2.3 and2.4 from the same graphical question?',commonMistakes:['claiming excessive decimal precision from a coarse graph','rounding before plotting','assuming graphical and algebraic answers must look textually identical']},
  {title:'Elimination idea when coefficients are already opposite',terms:[['eliminate','remove one variable by combining equations'],['coefficient','number multiplying a variable']],explain:'If one variable has equal coefficients with opposite signs, add the equations. The variable cancels immediately.',example:'2x+y=9 and3x−y=11. Add:5x=20→x=4. Substitute into first:8+y=9→y=1.',check:'Solve x+y=8 and2x−y=7 by elimination.',commonMistakes:['subtracting when opposite coefficients would add cleanly','adding y and−y incorrectly','forgetting to find the second variable']},
  {title:'Elimination when equal coefficients have the same sign',terms:[['equation subtraction','subtracting every term of one complete equation from the corresponding term of another']],explain:'If the chosen variable has equal coefficients with the same sign, subtract one equation from the other. Put brackets mentally around the equation being subtracted so every sign is handled.',example:'2x+3y=13 and2x+y=7. First minus second:2y=6→y=3. Then2x+3=7→x=2.',check:'Solve3x+2y=16 and3x−y=7.',commonMistakes:['subtracting only the x terms','forgetting that subtracting −y means adding y','mixing equation sides']},
  {title:'Preparing unequal coefficients using an LCM',terms:[['coefficient LCM','least common multiple used to make selected variable coefficients equal']],explain:'If coefficients differ, multiply complete equations by suitable factors. New General Mathematics emphasizes this. For3x−2y=24 and4x−9y=36, to eliminate x use LCM12: multiply the first equation by4 and the second by3.',example:'12x−8y=96 and12x−27y=108. Subtract:19y=−12→y=−12/19; then substitute for x. Fractional solutions are allowed.',check:'For2x+3y=7 and5x−2y=4, what multipliers would eliminate x?',commonMistakes:['multiplying only the x term','using HCF rather than a useful common multiple','assuming coefficients must originally match']},
  {title:'Choosing which variable to eliminate',terms:[['efficient choice','selection requiring the least arithmetic']],explain:'Either variable can be eliminated if done correctly. Prefer the variable whose coefficients are already equal/opposite or have a small LCM. This reduces arithmetic and sign errors.',example:'For4x+3y=18 and2x−3y=0, eliminate y immediately by adding rather than first changing x coefficients.',check:'For5x+2y=19 and5x−3y=4, which variable is most efficient to eliminate?',commonMistakes:['always eliminating x regardless of coefficients','creating unnecessarily large numbers','switching chosen variables halfway without structure']},
  {title:'Elimination requiring multiplication of one equation',terms:[['equivalent equation','equation obtained by multiplying every term by the same non-zero factor']],explain:'Sometimes only one equation needs scaling. Multiply every term—including the constant side—then combine.',example:'x+2y=8 and2x−y=1. To eliminate x, multiply first by2:2x+4y=16. Subtract second:5y=15→y=3; x+6=8→x=2.',check:'Solve x+3y=10 and2x−3y=5.',commonMistakes:['forgetting to multiply the RHS','multiplying one coefficient but not the other','combining before coefficients match']},
  {title:'Elimination requiring multiplication of both equations',terms:[['common coefficient','equal target coefficient created in both equations']],explain:'When neither coefficient divides the other conveniently, scale both equations. Keep equation numbers and write the multipliers; this protects exam working.',example:'2x+3y=12;3x+2y=13. Eliminate x: first×3→6x+9y=36; second×2→6x+4y=26; subtract→5y=10→y=2; then2x+6=12→x=3.',check:'Solve3x+4y=18 and5x+2y=16 by elimination.',commonMistakes:['using different operations on left and right sides','losing equation identity after scaling','not substituting back']},
  {title:'Elimination with negative values',terms:[['negative solution','valid variable value below zero']],explain:'Negative x or y is mathematically valid unless a real-life context forbids it. Maintain sign discipline through addition/subtraction.',example:'x+y=1 and x−y=5. Add:2x=6→x=3; then y=−2. Check:3+(−2)=1 and3−(−2)=5.',check:'Solve x+y=2 and x−y=8.',commonMistakes:['rejecting a negative answer automatically','forgetting minus a negative becomes plus','changing a sign when substituting']},
  {title:'Substitution method: the central idea',terms:[['substitution','replacing a variable by an equal expression'],['make subject','isolate one variable']],explain:'Rearrange one equation so x or y is alone, then replace that variable in the other equation. The second equation becomes an equation in one unknown.',example:'x+y=7→x=7−y. Substitute into2x+y=11:2(7−y)+y=11→14−y=11→y=3;x=4.',check:'Solve x+y=9 and x+2y=13 by substitution.',commonMistakes:['substituting into the same equation and learning nothing new','dropping brackets around an expression','not returning for the second variable']},
  {title:'Choosing the easiest variable for substitution',terms:[['unit coefficient','coefficient1 or−1']],explain:'Substitution is quickest when one variable already has coefficient1 or−1. Avoid creating fractions unnecessarily when another variable isolates cleanly.',example:'In x+3y=14 and2x−y=3, first equation gives x=14−3y immediately; second gives y=2x−3 immediately. Either is simple.',check:'Which variable would you isolate first in3x+y=10 and2x−5y=1, and why?',commonMistakes:['always isolating x','creating complicated fractions without need','changing signs incorrectly when moving terms']},
  {title:'Substitution with brackets',terms:[['replacement expression','whole algebraic expression substituted for a variable']],explain:'Use brackets around the substituted expression. If x=8−2y and the other equation contains3x, write3(8−2y), not3×8−2y.',example:'x+2y=8 and3x−y=3. x=8−2y. Then3(8−2y)−y=3→24−7y=3→y=3;x=2.',check:'If y=5−x, correctly substitute into2x+3y=11.',commonMistakes:['failing to multiply every term inside replacement brackets','dropping a negative sign','substituting a value before it has been found']},
  {title:'Substitution that produces fractions',terms:[['exact solution','fraction retained exactly rather than rounded']],explain:'Fractions are acceptable. Clear denominators carefully if they arise, or choose the other variable when that is simpler.',example:'2x+y=4 and3x−2y=1. y=4−2x. Substitute:3x−2(4−2x)=1→7x=9→x=9/7; y=10/7.',check:'Verify(9/7,10/7) in both equations.',commonMistakes:['rounding too early','rejecting non-integer answers','making arithmetic errors with fractional substitution']},
  {title:'Checking the ordered pair in both equations',terms:[['verification','testing the final pair against original conditions']],explain:'Substitute x and y into BOTH original equations. If either fails, the pair is not the simultaneous solution. This is especially important after long elimination arithmetic.',example:'For(3,2) in2x+3y=12 and3x+2y=13:6+6=12 and9+4=13.',check:'Check(2,3) in x+2y=8 and3x−y=3.',commonMistakes:['checking only the equation used last','checking a scaled equation instead of both originals','changing the pair order']},
  {title:'Comparing graphical, elimination and substitution methods',terms:[['method selection','choosing a valid approach suited to equation structure']],explain:'Graphing visualizes the common solution and is explicitly required by NERDC. Elimination is efficient when coefficients align easily. Substitution is efficient when a variable isolates easily. All should agree for the same pair, apart from graph-reading approximation.',example:'x+y=7, x−y=1: graph intersects(4,3); elimination gives2x=8→x=4,y=3; substitution gives the same.',check:'Which method would you choose first for y=2x+1 and3x+y=11, and why?',commonMistakes:['thinking different methods should produce different solutions','using graphing when an exact value is required but scale is poor','choosing a method without inspecting structure']},
  {title:'Word problems: constructing two equations',terms:[['unknowns','two quantities represented by x and y'],['independent equations','two distinct relationships needed to determine two unknowns']],explain:'Define both unknowns with units. Translate two separate facts into equations. Then solve using elimination or substitution and interpret the pair.',example:'Two numbers total20 and differ by4. Let x=larger,y=smaller. x+y=20; x−y=4. Add:2x=24→x=12,y=8.',check:'Form equations for two numbers whose sum is35 and difference is9.',commonMistakes:['using one equation for two unknowns','not defining which variable is which','forgetting that “difference” depends on order']},
  {title:'Cost and purchase problems',terms:[['unit cost','cost of one item'],['total cost','sum of quantity×unit cost']],explain:'Let variables represent unknown prices or quantities. One relationship often gives total number; another gives total cost. Keep currency units consistent.',example:'2 pens and3 books cost ₦900;4 pens and1 book cost ₦700. Let p,b be prices:2p+3b=900;4p+b=700. From second b=700−4p. Substitute:2p+2100−12p=900→−10p=−1200→p=120,b=220.',check:'Check that p=₦120,b=₦220 satisfies both totals.',commonMistakes:['adding prices without multiplying by quantities','mixing quantity and price variables','giving values without currency']},
  {title:'Ticket/quantity problems',terms:[['total count','sum of category quantities'],['weighted total','sum after multiplying each category by its value']],explain:'These are classic simultaneous-equation models. First equation counts items; second uses their individual values.',example:'Adult tickets cost ₦500, child tickets ₦300. If20 tickets bring ₦8,000, let a+c=20 and500a+300c=8000. Divide second by100:5a+3c=80. Substitute c=20−a:5a+60−3a=80→2a=20→a=10,c=10.',check:'Verify the ticket totals.',commonMistakes:['using money equation as a+ c=8000','forgetting to simplify large coefficients when useful','reporting negative counts without questioning the model']},
  {title:'Age problems with two unknowns',terms:[['age relation','equation connecting ages at the same or shifted time']],explain:'Define present ages unless told otherwise. Translate “sum”, “older than”, or future/past changes carefully. At JSS3, keep the resulting equations linear.',example:'A mother and daughter total54 years; mother is24 years older. m+d=54;m−d=24. Add:2m=78→m=39,d=15.',check:'A father and son total60 years and father is30 years older. Find both ages.',commonMistakes:['adding years to only one person when a future-time statement affects both','reversing older−younger','accepting impossible negative age']},
  {title:'Perimeter and measurement problems',terms:[['dimension','measurable length such as length or width']],explain:'Geometry can supply two linear relationships. Translate formulas first. For a rectangle, P=2(l+w). Another relationship between l and w gives the second equation.',example:'Perimeter40 and length is4 more than width: l+w=20;l−w=4. Add:2l=24→l=12,w=8.',check:'A rectangle has perimeter52 and length6 more than width. Find dimensions.',commonMistakes:['using l+w=P instead of half-perimeter','forgetting units','using area when perimeter is given']},
  {title:'Mixture of signs in word equations',terms:[['difference relation','one quantity minus another equals a stated difference']],explain:'Decide which quantity is larger before writing a difference equation. If x is explicitly larger, x−y=d. Then verify the final context.',example:'Two numbers sum18. One is6 greater than the other. Let x=greater: x+y=18;x−y=6→x=12,y=6.',check:'Two numbers sum41 and the larger exceeds the smaller by7. Find them.',commonMistakes:['writing y−x=7 after defining x as larger','using “greater than” backwards','not checking the sum']},
  {title:'BECE-style elimination with awkward coefficients',terms:[['scaling','multiplying complete equations to create eliminable coefficients']],explain:'Harder exam questions may require both equations to be scaled. Write the operation beside each equation to avoid confusion.',example:'3x+4y=18;5x+2y=16. Eliminate y: second×2→10x+4y=32. Subtract first:7x=14→x=2; then6+4y=18→y=3.',check:'Solve4x+3y=17 and5x−2y=4 by elimination.',commonMistakes:['scaling only one side','subtracting equations in inconsistent order','not simplifying a common factor in coefficients when useful']},
  {title:'BECE-style substitution with a negative expression',terms:[['negative subject form','isolated variable expressed with negative terms']],explain:'When substituting an expression containing subtraction, brackets are compulsory. Distribute any outside negative or coefficient across the whole expression.',example:'x−y=5→x=y+5. In2x+3y=20:2(y+5)+3y=20→5y=10→y=2,x=7.',check:'Solve y−x=1 and3x+2y=12 by substitution.',commonMistakes:['substituting x=y−5 instead of y+5','dropping brackets','changing a sign during distribution']},
  {title:'Special graph cases: parallel and coincident lines',terms:[['parallel lines','lines with same slope that never meet'],['coincident lines','same line represented by equivalent equations']],explain:'NERDC focuses on solving pairs graphically, but understanding the graph prevents false answers. Parallel distinct lines have no common solution. Equivalent equations produce the same line and therefore infinitely many common points. Standard BECE exercises usually seek one intersection, but learners should recognize these cases.',example:'x+y=3 and2x+2y=8 are parallel after simplification because second is x+y=4: no solution. x+y=3 and2x+2y=6 are the same line: infinitely many solutions.',check:'Classify x+y=5 and2x+2y=10.',commonMistakes:['inventing an intersection for parallel lines','calling coincident lines “one solution”','confusing close lines with identical lines']},
  {title:'Error diagnosis: elimination',terms:[['first invalid step','earliest transformation that breaks equivalence']],explain:'If2x+y=9 and3x−y=11 are added, correct result is5x=20. A student writing5x+2y=20 failed to cancel y+(−y). Diagnose the exact operation, then continue correctly.',example:'5x=20→x=4; substitute→y=1.',check:'A student subtracts (2x+y=7) from (2x+3y=13) and writes2y=20. Identify the error.',commonMistakes:['only saying the final answer is wrong','redoing without identifying the broken line','subtracting RHS incorrectly']},
  {title:'Error diagnosis: substitution',terms:[['bracket error','failure to treat a substituted expression as one grouped quantity']],explain:'If x=7−y and equation2x+y=11, substitution is2(7−y)+y=11, not14−y+y=11. The 2 multiplies both7 and−y.',example:'Correct:14−2y+y=11→−y=−3→y=3,x=4.',check:'Correct the substitution error3(5−2y)=15−2y.',commonMistakes:['multiplying only first term','losing negative signs','not verifying corrected pair']},
  {title:'Final BECE routine',terms:[['solution presentation','clear sequence of mathematical working suitable for assessment']],explain:'For algebraic solution: number equations; inspect coefficients; choose method; show scaling; eliminate/substitute; solve first variable; find second; check both equations. For graph: rearrange if needed; table both equations; choose/label scale; plot; draw lines; mark/read intersection; state pair. For word problems: define variables first and interpret units last.',example:'A complete answer ends “Therefore x=…, y=…” or gives the requested real quantities, followed by a quick verification.',check:'List the checks you should make before accepting a simultaneous-equation answer.',commonMistakes:['answer-only working','unlabelled graph','failure to answer the context after finding x and y']
  }
 ]
};

